package vn.edu.hunre.nhom11.carrental.content.domain;import jakarta.persistence.*;import java.time.Instant;@Entity@Table(name="news")public class News{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String title;@Column(nullable=false,length=5000)private String content;private String imageUrl;private boolean published=true;private Instant createdAt=Instant.now();public Long getId(){return id;}public void setId(Long v){id=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public String getImageUrl(){return imageUrl;}public void setImageUrl(String v){imageUrl=v;}public boolean isPublished(){return published;}public void setPublished(boolean v){published=v;}public Instant getCreatedAt(){return createdAt;}}

